INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N065-01','CN0311','S065-01','生产状态','2026半年报','一期与二期均已投产的公司披露，不自动证明各废水设施达到设计负荷。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N065-02','CN0311','S065-04','产能利用','2024年报','一期2024年8月投产，报告期产能利用率19.79%；不得以此推算废水流量。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N065-03','CN0311','S065-02','水处理与残余物','第二条（三）（六）','高浓水焚烧；低浓水预处理后纳管；废催化剂、精馏废液、塔顶废液等按危废委托。未列膜及分股流量。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N065-04','CN0312','S065-05','项目投资及污水边界','验收意见正文','总投资2100万元，环保投资100万元为综合环保，不能当成污水专属投资。旧站200m³/d与改造400、800m³/d阶段分开。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N065-05','CN0312','S065-06','扩产时间','企业介绍','企业称第三期拟2026年第四季度投产；未经独立验收核实。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N065-06','CN0313','S065-09','企业身份','技术创新中心名单','2026政府名单佐证主体，不能证明产线实际运行。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N065-07','CN0314','S065-10','运行及规模','2025报道','2022投产、2024产值4.07亿元；无实际吨数及废水工艺披露。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N065-08','CN0317','S065-13','项目和残余物','公示附件项目2','总投资10100万元、环保591万元是总环保投资；不得作为污水工程报价。截图接口405，使用政府附件可检索正文。','WEB_PRIMARY','WEB_TEXT','2026-11-28');
